      spareUuid: text2("spare_uuid").notNull().references(() => spares.suuid),
      // FK → spares.suuid
      locationId: integer2("location_id"),
      // Nullable only if non-location specific; for consume/receive MUST set
      locationUuid: text2("location_uuid"),
      // Companion UUID FK for cross-instance sync resolution → locations.luuid
      eventType: text2("event_type").notNull(),
      // RECEIVE | CONSUME | ADJUST_OPENING_BALANCE | ADJUST_CORRECTION
      qtyChange: integer2("qty_change").notNull(),
      // Positive for receive, negative for consume
      robTotalBefore: integer2("rob_total_before").notNull(),
      robTotalAfter: integer2("rob_total_after").notNull(),
      robLocationBefore: integer2("rob_location_before"),
      // Nullable if non-location specific
      robLocationAfter: integer2("rob_location_after"),
      // Nullable if non-location specific
      referenceType: text2("reference_type").notNull(),
      // WORK_ORDER | MANUAL | EXCEL_IMPORT
      referenceId: text2("reference_id"),
      // WO number, import batch id, etc.
      referenceNote: text2("reference_note"),
      // Free text
      userId: text2("user_id").notNull(),
      isSync: boolean2("is_sync").default(false),
      createdByUuid: text2("created_by_uuid"),
      updatedByUuid: text2("updated_by_uuid"),
