        for (const o of orphans) {
          reasonCounts[o.reason] = (reasonCounts[o.reason] || 0) + 1;
          console.warn(
            `[Provisioning] Skipping orphan planner_dates row pduuid=${o.pduuid} component_id=${o.component_id} reason="${o.reason}"`
          );
        }
