            batchUuid: null,
            recordsPushed: 0,
            recordsPulled: 0,
            conflictsFound: 0,
            conflictsAutoResolved: 0,
            filesQueued: 0,
            durationMs: 0,
            error: "A sync is already in progress for this vessel \u2014 please wait for it to finish.",
            newCheckpoint: null,
            remainingPush: null,
            remainingPull: null,
            remainingFilePull: null,
