  const parsedCanShipView = parseBoolean(body.canShipView);
  if (parsedCanShipView !== void 0) updateData.canShipView = parsedCanShipView;
  const parsedCanShipDownload = parseBoolean(body.canShipDownload);
  if (parsedCanShipDownload !== void 0) updateData.canShipDownload = parsedCanShipDownload;
