async function exportHistory(req, res) {
  try {
    const vesselId = req.query.vesselId || "";
    const componentId = req.query.componentId;
    const sortOrder = req.query.sortOrder === "asc" ? "asc" : "desc";
    const search = req.query.search;
    const dateFrom = req.query.dateFrom;
    const dateTo = req.query.dateTo;
    const result = await getRunningHoursHistory2({
      vesselId,
      componentId,
      page: 1,
      pageSize: 1e4,
      sortOrder,
      search,
      dateFrom,
      dateTo
    });
    const headers = ["Date", "Component Code", "Component Name", "Previous RH", "New RH", "Change (Delta)", "Updated By", "Source", "Notes"];
    const rows = result.data.map((row) => [
      row.updatedAt ? new Date(row.updatedAt).toISOString().split("T")[0] : "",
      row.componentCode,
      row.componentName || "",
      row.previousRh,
      row.newRh,
      row.deltaRh,
      row.updatedBy,
      row.updateSource,
      row.notes || ""
    ]);
    const csvContent = [
      headers.join(","),
      ...rows.map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(","))
    ].join("\n");
    res.setHeader("Content-Type", "text/csv");
    res.setHeader("Content-Disposition", `attachment; filename="running_hours_history_${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.csv"`);
    res.send(csvContent);
  } catch (error) {
    console.error("Error exporting running hours history:", error);
    res.status(500).json({ error: "Failed to export running hours history" });
  }
}

