async function bulkUpdate(vesselId, rows) {
  const results = [];
  for (const row of rows) {
    const {
      componentSpareId,
      consumedA = 0,
      consumedB = 0,
      receivedA = 0,
      receivedB = 0,
      receivedDate,
      receivedPlace,
      dateLocal,
      remarks,
      userId = "user"
    } = row;
    const transactionDate = receivedDate && receivedDate.trim() ? receivedDate.trim() : dateLocal && dateLocal.trim() ? dateLocal.trim() : void 0;
    try {
      let totalChange = 0;
      const errors = [];
      if (consumedA > 0) {
        try {
          await consumeSpareFromLocation(
            componentSpareId,
            consumedA,
            "A",
            userId,
            remarks,
            void 0,
            // workOrderRef
            transactionDate
          );
          totalChange -= consumedA;
        } catch (e) {
          errors.push(`Consume A: ${e.message}`);
        }
      }
      if (consumedB > 0) {
        try {
          await consumeSpareFromLocation(
            componentSpareId,
            consumedB,
            "B",
            userId,
            remarks,
            void 0,
            // workOrderRef
            transactionDate
          );
          totalChange -= consumedB;
        } catch (e) {
          errors.push(`Consume B: ${e.message}`);
        }
      }
      if (receivedA > 0) {
        try {
          await receiveSpareToLocation(
            componentSpareId,
            receivedA,
            "A",
            userId,
            remarks,
            receivedPlace,
            transactionDate
          );
          totalChange += receivedA;
        } catch (e) {
          errors.push(`Receive A: ${e.message}`);
        }
      }
      if (receivedB > 0) {
        try {
          await receiveSpareToLocation(
            componentSpareId,
            receivedB,
            "B",
            userId,
            remarks,
            receivedPlace,
            transactionDate
          );
          totalChange += receivedB;
        } catch (e) {
          errors.push(`Receive B: ${e.message}`);
        }
      }
      const spare = await getSpare(componentSpareId);
      if (errors.length > 0) {
        results.push({
          componentSpareId,
          success: false,
          message: errors.join("; "),
          robAfter: spare?.rob
        });
      } else {
        results.push({
          componentSpareId,
          success: true,
          robAfter: spare?.rob
        });
      }
    } catch (error) {
      results.push({
        componentSpareId,
        success: false,
        message: error.message || "Unknown error"
      });
    }
  }
  return results;
}
async function batchConsume(items, workOrderId, consumedBy) {
  const results = [];
  for (const item of items) {
    const result = await consumeSpare(
      item.spareId,
      item.quantity,
      workOrderId,
      consumedBy || "System",
      item.notes
    );
    results.push(result);
  }
  return results;
}
async function batchReceive(items, purchaseOrderRef, receivedBy) {
  const results = [];
  for (const item of items) {
    const result = await receiveSpare(
      item.spareId,
      item.quantity,
      receivedBy || "System",
      item.notes,
      purchaseOrderRef
    );
    results.push(result);
  }
  return results;
}
async function consumeSimple(spareId, body) {
  const { qty, dateLocal, place, remarks, userId, workOrder } = body;
  if (!qty || qty <= 0) {
    throw Object.assign(new Error("Quantity must be a positive number"), { statusCode: 400 });
  }
  const result = await consumeSpareFromLocation(
    spareId,
    qty,
    "A",
    userId || "User",
    remarks || `Consumed at ${place || "unknown location"} on ${dateLocal}`,
    workOrder
  );
  return {
    success: true,
    message: "Spare consumed successfully",
    data: result
  };
}
async function receiveSimple(spareId, body) {
  const { qty, dateLocal, supplierPO, remarks, userId } = body;
  if (!qty || qty <= 0) {
    throw Object.assign(new Error("Quantity must be a positive number"), { statusCode: 400 });
  }
  const spare = await getSpare(spareId);
  if (!spare) {
    throw Object.assign(new Error("Spare not found"), { statusCode: 404 });
  }
  const newRobLocationA = (spare.robLocationA || 0) + qty;
  const updatedSpare = await updateSpare(spareId, {
    robLocationA: newRobLocationA
  });
  return {
    success: true,
    message: "Spare received successfully",
    data: updatedSpare
  };
}
async function consumeFromLocation(paramsRaw, bodyRaw) {
  const paramsResult = consumeFromLocationParamsSchema.safeParse(paramsRaw);
  if (!paramsResult.success) {
    return {
      validationError: true,
      statusCode: 400,
      response: {
        success: false,
        error: {
          code: "VALIDATION_ERROR",
          message: paramsResult.error.errors[0]?.message || "Invalid spare ID",
          field: "id"
        }
      }
    };
  }
  const bodyResult = consumeFromLocationBodySchema.safeParse(bodyRaw);
  if (!bodyResult.success) {
    return {
      validationError: true,
      statusCode: 400,
      response: {
        success: false,
        errors: bodyResult.error.errors.map((err) => ({
          code: "VALIDATION_ERROR",
          message: err.message,
          field: err.path.join(".")
        }))
      }
    };
  }
  const { id: spareId } = paramsResult.data;
  const { quantity, location, userId, remarks, workOrderRef } = bodyResult.data;
  const result = await consumeSpareFromLocation(
    spareId,
    quantity,
    location,
    userId || "system",
    remarks,
    workOrderRef
  );
  if (result.shortageQty > 0) {
    return {
      validationError: false,
      response: {
        success: true,
        data: result,
        warning: {
          code: "PARTIAL_CONSUMPTION",
          message: `Requested ${result.requested} but only ${result.deducted} available at Location ${location}`,
          shortageQty: result.shortageQty
        }
      }
    };
  }
  return { validationError: false, response: { success: true, data: result } };
}
