async function getCertificate2(req, res) {
  try {
    const certificate = await getCertificate(req.params.id);
    if (!certificate) {
      return res.status(404).json({ error: "Certificate not found" });
    }
    res.json(certificate);
  } catch (error) {
    if (error.code === "MASTER_NOT_FOUND") {
      return res.status(404).json({ error: "Certificate master not found" });
    }
    console.error("Error fetching certificate:", error);
    res.status(500).json({ error: "Failed to fetch certificate" });
  }
}
async function updateCertificate2(req, res) {
  try {
    const result = await updateCertificate(req.params.id, req.body);
    res.json(result);
  } catch (error) {
    if (error.statusCode === 400) {
      return res.status(400).json({ error: error.message });
    }
    console.error("Error updating certificate:", error);
    res.status(500).json({ error: "Failed to update certificate" });
  }
}

