async function getMasterDataList2(query) {
  const { sfiCode, vesselName, modelCode, limit, offset } = query;
  let entries = await getMasterDataList();
  if (sfiCode) {
    entries = entries.filter((e) => e.sfiCode === sfiCode);
  }
  if (vesselName) {
    entries = entries.filter((e) => e.vesselName === vesselName);
  }
  if (modelCode) {
    entries = entries.filter((e) => e.modelCode === modelCode);
  }
  const total = entries.length;
  const limitNum = limit ? parseInt(limit) : 100;
  const offsetNum = offset ? parseInt(offset) : 0;
  entries = entries.slice(offsetNum, offsetNum + limitNum);
  return { items: entries, total, limit: limitNum, offset: offsetNum };
}
