async function exportFleetComponents() {
  const XLSXModule = await import("xlsx");
  const allComponents = await getFleetComponents();
  const headers = [
    "Parent Fleet Equipment Code",
    "Fleet Equipment Code",
    "Fleet Equipment Name",
    "Component Category",
    "Maker Name",
    "Maker Code",
    "Model",
    "Model Code",
    "Location",
    "Rating",
    "Eqpt / System Department",
    "Notes",
    "IS Active"
  ];
  const rows = allComponents.map((c) => [
    c.parentFleetEquipmentCode || "",
    c.fleetEquipmentCode || "",
    c.fleetEquipmentName || "",
    c.componentCategory || "",
    c.makerName || "",
    c.makerCode || "",
    c.model || "",
    c.modelCode || "",
    c.location || "",
    c.rating || "",
    c.eqptSystemDept || "",
    c.notes || "",
    c.isActive === false ? "No" : "Yes"
  ]);
  const wsData = [headers, ...rows];
  const ws = XLSXModule.utils.aoa_to_sheet(wsData);
  const colWidths = [25, 25, 40, 20, 25, 15, 20, 15, 20, 15, 25, 30, 10];
  ws["!cols"] = colWidths.map((w) => ({ wch: w }));
  const wb = XLSXModule.utils.book_new();
  XLSXModule.utils.book_append_sheet(wb, ws, "Fleet Components");
  return {
    buffer: XLSXModule.write(wb, { type: "buffer", bookType: "xlsx" }),
    filename: `fleet-components-${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.xlsx`
  };
}
