async function mapVesselWithAutoLinkage(body) {
  const schema = z5.object({
    fleetEquipmentCode: z5.string(),
    vesselCode: z5.string(),
    vesselName: z5.string()
  });
  const { fleetEquipmentCode, vesselCode, vesselName } = schema.parse(body);
  const vesselComponents = await getVesselComponentsByFleetEquipmentPrefix(vesselCode, fleetEquipmentCode);
  const parentVesselComp = vesselComponents.find((vc) => vc.fleetEquipmentCode === fleetEquipmentCode);
  let parentMapping = null;
  try {
    parentMapping = await createFleetComponentMappingRecord({
      fleetEquipmentCode,
      vesselCode,
      componentCode: parentVesselComp?.componentCode || fleetEquipmentCode,
      componentName: parentVesselComp?.name || void 0,
      componentId: parentVesselComp?.cuuid || void 0,
      mappedBy: "admin",
      isActive: true
    });
  } catch (err) {
    if (!err.message?.includes("unique") && !err.message?.includes("duplicate")) throw err;
  }
  let linkedCount = 0;
  for (const vc of vesselComponents) {
    if (vc.componentCode && vc.componentCode !== fleetEquipmentCode) {
      try {
        await createFleetComponentMappingRecord({
          fleetEquipmentCode: vc.fleetEquipmentCode || fleetEquipmentCode,
          vesselCode,
          componentCode: vc.componentCode,
          componentName: vc.name || vc.fleetEquipmentName || void 0,
          componentId: vc.cuuid || void 0,
          mappedBy: "admin",
          isActive: true
        });
        linkedCount++;
      } catch (err) {
        if (!err.message?.includes("unique") && !err.message?.includes("duplicate")) throw err;
      }
    }
  }
  return {
    parentMapping,
    linkedComponents: linkedCount,
    totalVesselComponents: vesselComponents.length
  };
}
