async function getCriticalSparesPreview2(req, res) {
  try {
    const vesselId = req.query.vesselId;
    if (!vesselId) {
      return res.status(400).json({ error: "vesselId is required" });
    }
    const stockStatusFilter = req.query.stockStatus ? Array.isArray(req.query.stockStatus) ? req.query.stockStatus : [req.query.stockStatus] : null;
    const departmentFilter = req.query.department;
    const vesselIds = req.query.vesselIds ? req.query.vesselIds.split(",").filter(Boolean) : void 0;
    const result = await getCriticalSparesPreview(vesselId, stockStatusFilter, departmentFilter, vesselIds);
    res.json(result);
  } catch (error) {
    console.error("Error generating critical spares preview:", error);
    res.status(500).json({
      success: false,
      error: error.message || "Failed to generate critical spares report"
    });
  }
}
