// server/modules/reports/controllers/favoritesController.ts
init_schema();
init_db();
import { eq as eq23, and as and20 } from "drizzle-orm";
function getUserUuid(req) {
  return req.user?.userUuid || null;
}
async function getFavorites(req, res) {
  try {
    const userUuid = getUserUuid(req);
    if (!userUuid) {
      return res.status(401).json({ error: "Authentication required" });
    }
    const db2 = await getDb();
    const favorites = await db2.select({ reportId: reportFavorites.reportId }).from(reportFavorites).where(
      and20(
        eq23(reportFavorites.createdByUuid, userUuid),
        eq23(reportFavorites.isDeleted, false)
      )
    );
    res.json({ reportIds: favorites.map((f) => f.reportId) });
  } catch (error) {
    console.error("Error fetching report favorites:", error);
    res.status(500).json({ error: error.message || "Failed to fetch favorites" });
  }
}
async function addFavorite(req, res) {
  try {
    const userUuid = getUserUuid(req);
    if (!userUuid) {
      return res.status(401).json({ error: "Authentication required" });
    }
    const { reportId } = req.params;
    if (!reportId) {
      return res.status(400).json({ error: "reportId is required" });
    }
    const db2 = await getDb();
    const existing = await db2.select().from(reportFavorites).where(
      and20(
        eq23(reportFavorites.createdByUuid, userUuid),
        eq23(reportFavorites.reportId, reportId)
      )
    ).limit(1);
    if (existing.length > 0) {
      if (existing[0].isDeleted) {
        await db2.update(reportFavorites).set({
          isDeleted: false,
          updatedByUuid: userUuid
        }).where(eq23(reportFavorites.id, existing[0].id));
      }
      return res.json({ success: true, reportId });
    }
    await db2.insert(reportFavorites).values({
      reportId,
      createdByUuid: userUuid,
      updatedByUuid: userUuid
    });
    res.json({ success: true, reportId });
  } catch (error) {
    console.error("Error adding report favorite:", error);
    res.status(500).json({ error: error.message || "Failed to add favorite" });
  }
}
async function removeFavorite(req, res) {
  try {
    const userUuid = getUserUuid(req);
    if (!userUuid) {
      return res.status(401).json({ error: "Authentication required" });
    }
    const { reportId } = req.params;
    if (!reportId) {
      return res.status(400).json({ error: "reportId is required" });
    }
    const db2 = await getDb();
    await db2.update(reportFavorites).set({
      isDeleted: true,
      updatedByUuid: userUuid
    }).where(
      and20(
        eq23(reportFavorites.createdByUuid, userUuid),
        eq23(reportFavorites.reportId, reportId)
      )
    );
    res.json({ success: true, reportId });
  } catch (error) {
    console.error("Error removing report favorite:", error);
    res.status(500).json({ error: error.message || "Failed to remove favorite" });
  }
}

