async function getSheets(req, res) {
  try {
    const file = req.file;
    if (!file) {
      return res.status(400).json({ error: "No file uploaded" });
    }
    const ext = path9.extname(file.originalname).toLowerCase();
    if (ext === ".csv") {
      return res.json({ sheets: ["Sheet1"] });
    } else if ([".xlsx", ".xls"].includes(ext)) {
      const workbook = XLSX4.read(file.buffer);
      return res.json({ sheets: workbook.SheetNames });
    } else {
      return res.status(400).json({ error: "Unsupported file format" });
    }
  } catch (error) {
    console.error("Error reading sheets:", error);
    res.status(500).json({ error: "Failed to read file sheets" });
  }
}
