// server/middleware/exemptPaths.ts
var EXEMPT_EXACT = [
  "/sync/instance-info",
  "/sync/health",
  // server-to-server protocol routes (guarded by syncTenantGuard)
  "/sync/initiate",
  "/sync/push",
  "/sync/pull",
  "/sync/complete",
  "/sync/file/upload-chunk",
  // shore→ship file PULL (mirror of upload-chunk; also guarded by syncTenantGuard).
  // Ships call these server-to-server with X-Sync-* (no SAILERP Bearer) — must bypass
  // tenantMiddleware like the push, or they'd 401 before the guard runs.
  "/sync/file/pending",
  "/sync/file/download-chunk"
];
var EXEMPT_PATTERNS = [
  /^\/sync\/file\/[^/]+\/(complete|fail)$/
];
function isExemptPath(relPath) {
  const p = (relPath.split("?")[0] || "/").replace(/\/+$/, "") || "/";
  if (EXEMPT_EXACT.includes(p)) return true;
  return EXEMPT_PATTERNS.some((re) => re.test(p));
}

// server/middleware/tenantMiddleware.ts
var IS_DEV = process.env.NODE_ENV === "development";
var AUTH_BYPASS = process.env.AUTH_BYPASS === "true" && IS_DEV;
function extractBearer(req) {
  const raw = req.headers["authorization"];
  const value = Array.isArray(raw) ? raw[0] : raw;
  if (typeof value !== "string") return null;
  const m = value.match(/^Bearer\s+(.+)$/i);
  return m ? m[1].trim() : null;
}
function tenantMiddleware(req, res, next) {
  if (!tenantConnectionManager.isMultiTenantEnabled) return next();
  if (AUTH_BYPASS) return next();
  if (isExemptPath(req.path)) return next();
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "server_misconfigured", message: "JWT_SECRET not set in multi-tenant mode" });
    return;
  }
  const token = extractBearer(req);
  if (!token) {
    res.status(401).json({ error: "unauthorized", message: "Missing authorization token" });
    return;
  }
  let payload;
  try {
    payload = jwt.verify(token, secret, { algorithms: ["HS256"] });
  } catch (err) {
    if (err && err.name === "TokenExpiredError") {
      res.status(401).json({ error: "token_expired", message: "Authorization token has expired" });
      return;
    }
    res.status(401).json({ error: "invalid_token", message: "Invalid authorization token" });
    return;
  }
  const domain = typeof payload === "object" && typeof payload.domain === "string" ? payload.domain.trim() : "";
  if (!domain) {
    res.status(401).json({ error: "invalid_token", message: "Token is missing the domain claim" });
    return;
  }
  req.tenantDomain = domain;
  tenantConnectionManager.resolveTenant(domain).then(
    (tenant) => (
      // Keep the ALS context open for the whole request (mirrors Crewing): the rest of
      // the chain — mockAuthMiddleware, requestContext, moduleRouter, handlers — runs
      // inside runInTenantContext, so getDb()/getPool() hit the tenant DB.
      tenantConnectionManager.runInTenantContext(
        tenant.tuid,
        () => new Promise((resolve6, reject) => {
          res.on("finish", resolve6);
          res.on("close", resolve6);
          res.on("error", reject);
          req.tenantTuid = tenant.tuid;
          next();
        })
      )
    )
  ).catch((err) => {
    if (res.headersSent) return;
    switch (err?.name) {
      case "TenantNotFoundError":
        res.status(403).json({ error: "invalid_tenant", message: err.message });
        return;
      case "TenantInactiveError":
        res.status(403).json({ error: "tenant_inactive", message: err.message });
        return;
      default:
        res.status(503).json({ error: "tenant_unavailable", message: "Tenant database unavailable" });
    }
  });
}

